// ── Client: Making credentialed cross-origin requests ────────

// DEFAULT: cross-origin fetch does NOT send cookies
const publicData = await fetch('https://api.example.com/products');
// Cookies not sent — no credentials

// To send cookies cross-origin, use credentials: 'include'
// The server must have Access-Control-Allow-Credentials: true
// AND a specific origin (not *) in Access-Control-Allow-Origin
const userProfile = await fetch('https://api.example.com/me', {
  credentials: 'include',
});

// ── Server: Express.js CORS middleware (conceptual) ───────────
const ALLOWED_ORIGINS = new Set([
  'https://app.example.com',
  'https://admin.example.com',
]);

function corsMiddleware(req, res, next) {
  const origin = req.headers['origin'];

  // Handle preflight
  if (req.method === 'OPTIONS') {
    if (ALLOWED_ORIGINS.has(origin)) {
      res.setHeader('Access-Control-Allow-Origin', origin);
      res.setHeader('Access-Control-Allow-Credentials', 'true');
      res.setHeader('Access-Control-Allow-Methods',
        'GET, POST, PUT, PATCH, DELETE');
      res.setHeader('Access-Control-Allow-Headers',
        'Content-Type, Authorization, X-Request-ID');
      // Cache preflight for 24 hours
      res.setHeader('Access-Control-Max-Age', '86400');
      // Vary: Origin tells CDNs to cache different responses per origin
      res.setHeader('Vary', 'Origin');
    }
    return res.status(204).end();
  }

  // Handle actual request
  if (ALLOWED_ORIGINS.has(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
    res.setHeader('Access-Control-Allow-Credentials', 'true');
    // Expose custom response headers to JS
    res.setHeader('Access-Control-Expose-Headers',
      'X-Total-Count, X-Request-ID');
    res.setHeader('Vary', 'Origin');
  }

  next();
}

// ── Cookie setup on the server for cross-origin auth ─────────
function setAuthCookie(res, token) {
  res.setHeader('Set-Cookie', [
    `session=${token}`,
    'HttpOnly',         // JS cannot read this
    'Secure',           // HTTPS only
    'SameSite=None',    // Required for cross-site iframe/API contexts
    'Max-Age=86400',
    'Path=/',
  ].join('; '));
}

// IMPORTANT: SameSite=None requires Secure.
// SameSite=Strict or Lax is preferred for first-party auth cookies.
// Only use None when the cookie MUST cross origins (third-party embeds).

